import { contentWords, normalizeWords } from "./cheetah-memory-layers.js";

/**
 * Deterministic question + gold-answer generation over an article that was
 * taught into the knowledge base.
 *
 * A memory benchmark is only meaningful if the expected answer is fixed before
 * the model is asked, and is fixed from the *source*, not from anything the
 * model produced. Every question here is therefore built by matching a literal
 * pattern in the article text, and its gold answer is the span that pattern
 * captured. Nothing is generated by a model, so a wrong answer cannot be
 * excused by a wrong question.
 */

const AGENT_VERBS = {
  founded: "founded",
  written: "wrote",
  directed: "directed",
  created: "created",
  designed: "designed",
  composed: "composed",
  produced: "produced",
  developed: "developed",
  discovered: "discovered",
  published: "published",
  painted: "painted",
  invented: "invented",
};

const YEAR_VERBS = [
  "built", "completed", "founded", "established", "opened", "released",
  "published", "born", "created", "formed", "introduced", "launched",
  "decommissioned", "inaugurated", "adopted", "discovered", "recorded",
  "constructed", "elected", "signed",
];

function collapse(value) {
  return String(value ?? "").replace(/\s+/g, " ").trim();
}

function splitSentences(text) {
  return collapse(text)
    .split(/(?<=[.!?])\s+(?=[A-Z"'(\d])/u)
    .map((sentence) => sentence.trim())
    .filter(Boolean);
}

function cleanSpan(value, { maxWords = 12 } = {}) {
  const cleaned = collapse(value)
    .replace(/^[,;:\-–—\s]+/, "")
    .replace(/[,;:.\s]+$/, "")
    .replace(/\s*\([^)]*\)\s*$/, "");
  const words = cleaned.split(/\s+/);
  return words.slice(0, maxWords).join(" ").replace(/[,;:.]+$/, "");
}

/**
 * Build every question this article deterministically supports.
 * Each spec carries the exact source sentence its gold answer came from, so the
 * report can show what "correct" was measured against.
 */
export function buildQuestionsForArticle({
  title,
  subjectId,
  subjectType = "other",
  passages = [],
  text = "",
} = {}) {
  const cleanTitle = collapse(title);
  if (!cleanTitle) {
    return [];
  }
  const gist = passages[0]?.text ?? collapse(text).slice(0, 320);
  const body = passages.length ? passages.map((passage) => passage.text).join(" ") : collapse(text);
  const sentences = splitSentences(body);
  const questions = [];
  const push = (spec) => {
    if (!spec?.goldAnswer || cleanSpan(spec.goldAnswer).length < 2) {
      return;
    }
    // A gold answer that is only the subject's own name tests nothing.
    const goldWords = contentWords(spec.goldAnswer);
    const titleWords = new Set(normalizeWords(cleanTitle));
    if (!goldWords.length || goldWords.every((word) => titleWords.has(word))) {
      return;
    }
    questions.push({
      subject: cleanTitle,
      subjectId,
      expect: "answerable",
      ...spec,
      goldAnswer: cleanSpan(spec.goldAnswer, { maxWords: spec.kind === "year" ? 2 : 12 }),
    });
  };

  push({
    kind: "broad",
    question: `What do you know about ${cleanTitle}?`,
    goldAnswer: gist,
    goldSentence: gist,
  });

  // A period ends the span only when a capital letter follows it: `U.S.` inside
  // "a reservoir in the U.S. state of Virginia" is part of the answer, and a
  // plain `[^.]` capture silently truncated every gold answer at it. The
  // leading verbs are spelled out in both cases instead of using the `i` flag,
  // because `i` would also case-fold the `[A-Z]` in that lookahead and bring
  // the truncation straight back.
  const definition =
    /\b(?:[Ii]s|[Ww]as|[Aa]re|[Ww]ere)\s+(?:an?|the)\s+((?:[^,;.]|\.(?!\s+[A-Z]|\s*$)){5,90})/.exec(
      gist,
    );
  if (definition) {
    push({
      kind: "definition",
      question:
        subjectType === "person"
          ? `What was ${cleanTitle} known for doing?`
          : `What kind of thing is ${cleanTitle}?`,
      goldAnswer: definition[1],
      goldSentence: sentences.find((sentence) => sentence.includes(definition[1].slice(0, 30))) ?? gist,
    });
  }

  const titleTokens = contentWords(cleanTitle);
  for (const [sentenceIndex, sentence] of sentences.entries()) {
    const sentenceWords = new Set(normalizeWords(sentence));
    const namesSubject = titleTokens.some((token) => sentenceWords.has(token));
    // A sentence deep in the article that never names the subject is usually
    // about something else — "The show was created by Ernie Johnson" in a
    // biography would otherwise yield "Who created Marc Fein?". The opening
    // sentences are exempt: there, "It" unambiguously refers to the subject.
    const aboutSubject = namesSubject || sentenceIndex < 2;
    const yearPattern = new RegExp(
      `\\b(?:was|were|is|are)\\s+(${YEAR_VERBS.join("|")})\\b[^.]{0,50}?\\b(?:in|on)\\s+(?:[A-Z][a-z]+\\s+\\d{1,2},?\\s*)?(1[0-9]{3}|20[0-9]{2})\\b`,
      "i",
    );
    const year = yearPattern.exec(sentence);
    if (year && aboutSubject && !questions.some((entry) => entry.kind === "year")) {
      push({
        kind: "year",
        question: `In what year was ${cleanTitle} ${year[1].toLowerCase()}?`,
        goldAnswer: year[2],
        goldSentence: sentence,
      });
    }

    const location =
      /\b(?:is|was)\s+(?:a|an|the)(?:[^;.]|\.(?!\s+[A-Z]|\s*$)){0,70}?\bin\s+((?:the\s+)?[A-Z][\p{L}'’.-]*(?:[ ,]+(?:of\s+)?[A-Z][\p{L}'’.-]*){0,3})/u.exec(
        sentence,
      ) ?? /\b(?:located|situated|based)\s+(?:in|at|near)\s+((?:the\s+)?[A-Z][\p{L}'’.-]*(?:[ ,]+[A-Z][\p{L}'’.-]*){0,3})/u.exec(sentence);
    if (location && aboutSubject && !questions.some((entry) => entry.kind === "location")) {
      push({
        kind: "location",
        question: `Where is ${cleanTitle} located?`,
        goldAnswer: location[1],
        goldSentence: sentence,
      });
    }

    const agent = new RegExp(
      `\\b(${Object.keys(AGENT_VERBS).join("|")})\\s+by\\s+([A-Z][\\p{L}'’.-]*(?:\\s+[A-Z][\\p{L}'’.-]*){0,3})`,
      "u",
    ).exec(sentence);
    if (agent && namesSubject && !questions.some((entry) => entry.kind === "agent")) {
      push({
        kind: "agent",
        question: `Who ${AGENT_VERBS[agent[1].toLowerCase()] ?? agent[1]} ${cleanTitle}?`,
        goldAnswer: agent[2],
        goldSentence: sentence,
      });
    }

    const partOf = /\b(?:is|was)\s+(?:part of|a member of|owned by|operated by|run by|home to|home of)\s+((?:the\s+)?[A-Z][\p{L}'’.-]*(?:\s+[A-Z][\p{L}'’.-]*){0,4})/u.exec(
      sentence,
    );
    if (partOf && namesSubject && !questions.some((entry) => entry.kind === "affiliation")) {
      push({
        kind: "affiliation",
        question: `What is ${cleanTitle} associated with or part of?`,
        goldAnswer: partOf[1],
        goldSentence: sentence,
      });
    }
  }

  return questions;
}

/**
 * A control question about a subject that was deliberately never taught. A
 * correct system declines; anything else is a hallucination that retrieval
 * failed to stop.
 */
export function buildControlQuestion({ title }) {
  const cleanTitle = collapse(title);
  return {
    kind: "control",
    subject: cleanTitle,
    subjectId: null,
    expect: "decline",
    question: `What do you know about ${cleanTitle}?`,
    goldAnswer: null,
    goldSentence: null,
  };
}

/**
 * Pick a varied benchmark set: at most one question per article per kind, a cap
 * on how much of the set may be the easy broad question, and round-robin over
 * the kinds so the report is not dominated by whichever pattern happens to be
 * most common in the corpus.
 */
export function selectBenchmarkQuestions(
  candidatesByArticle,
  { total = 50, maxBroadShare = 0.3, maxPerArticle = 2 } = {},
) {
  const buckets = new Map();
  for (const candidates of candidatesByArticle) {
    for (const candidate of candidates) {
      if (!buckets.has(candidate.kind)) {
        buckets.set(candidate.kind, []);
      }
      buckets.get(candidate.kind).push(candidate);
    }
  }
  const broadCap = Math.floor(total * maxBroadShare);
  const perArticle = new Map();
  const selected = [];
  const order = [...buckets.keys()].sort((left, right) => {
    if (left === "broad") return 1;
    if (right === "broad") return -1;
    return buckets.get(right).length - buckets.get(left).length;
  });
  let progress = true;
  while (selected.length < total && progress) {
    progress = false;
    for (const kind of order) {
      if (selected.length >= total) {
        break;
      }
      const bucket = buckets.get(kind);
      while (bucket.length) {
        const candidate = bucket.shift();
        const used = perArticle.get(candidate.subject) ?? 0;
        if (used >= maxPerArticle) {
          continue;
        }
        if (kind === "broad" && selected.filter((entry) => entry.kind === "broad").length >= broadCap) {
          break;
        }
        perArticle.set(candidate.subject, used + 1);
        selected.push(candidate);
        progress = true;
        break;
      }
    }
  }
  return selected;
}

/**
 * Score one answer against its gold span.
 *
 * `goldRecall` is the measure that decides correctness: how much of the gold
 * answer's own content the reply actually contains. A year question is scored
 * on the exact token, because "2011" either appears or it does not.
 */
export function scoreAnswer(answer, { kind, goldAnswer, goldSentence } = {}) {
  const text = collapse(answer);
  const abstained = /\b(i\s+(?:do\s+not|don['’]?t)\s+know|unknown|no\s+answer|not\s+(?:sure|known))\b/i.test(
    text,
  );
  if (!text || abstained) {
    return { correct: false, abstained: true, goldRecall: 0, evidencePrecision: 0, empty: !text };
  }
  if (!goldAnswer) {
    return { correct: false, abstained: false, goldRecall: 0, evidencePrecision: 0, empty: false };
  }
  const answerWords = new Set(normalizeWords(text));
  const goldWords = contentWords(goldAnswer);
  const goldRecall = goldWords.length
    ? goldWords.filter((word) => answerWords.has(word)).length / goldWords.length
    : 0;
  const sentenceWords = new Set(normalizeWords(goldSentence ?? goldAnswer));
  const replyWords = contentWords(text);
  const evidencePrecision = replyWords.length
    ? replyWords.filter((word) => sentenceWords.has(word)).length / replyWords.length
    : 0;
  const threshold = kind === "broad" ? 0.5 : 0.6;
  const correct = kind === "year" ? answerWords.has(String(goldAnswer).toLowerCase()) : goldRecall >= threshold;
  return { correct, abstained: false, goldRecall, evidencePrecision, empty: false };
}

export { splitSentences };
